398. pub struct UserInv;
399. pub open spec const USER_INV: int = 5;
400. impl InvariantPredicate<Loc, FlagToken> for UserInv {
401.     open spec fn inv(id: Loc, token: FlagToken) -> bool {
402.         &&& token.id() == id
403.     }
404. }
